"""Write generated files without silently losing what someone changed in them: a file that
differs from what roadie wrote last is kept as <name>.mine-<YYYYMMDD>.bak before it is replaced."""

import hashlib
import os
import shutil
import time
from pathlib import Path

from roadie import system
from roadie.render import HEADER, RenderedFile
from roadie.render.envfiles import ENV_HEADER

# header lines of this and older roadie versions: a file that differs only there is roadie's own
_OLD_HEADER = "Generated by roadie. Changes are overwritten when the wizard runs again."
_HEADER_LINES = {f"# {line}" for line in (_OLD_HEADER, *HEADER.splitlines())} | {ENV_HEADER}


def _sha(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def _without_header(data: bytes) -> list[bytes]:
    return [line for line in data.splitlines() if line.decode("utf-8", "replace") not in _HEADER_LINES]


def target(ctx, f: RenderedFile, base: Path) -> Path:
    return ctx.paths.root / f.path.lstrip("/") if f.path.startswith("/") else base / f.path


def _copy_path(path: Path) -> Path:
    # ".bak": apt, sshd, fail2ban and Traefik all skip such files without a notice
    name = f"{path.name}.mine-{time.strftime('%Y%m%d')}"
    copy, n = path.with_name(f"{name}.bak"), 2
    while copy.exists() or copy.is_symlink():
        copy, n = path.with_name(f"{name}-{n}.bak"), n + 1
    return copy


def write_guarded(ctx, files: list[RenderedFile], base: Path) -> None:
    """Like system.write_files, but a file someone changed is copied first (ctx.extra
    "mine_copies": (path, copy) pairs) and a file with the same content is left alone.
    Copies of files roadie has no record of are also in ctx.extra "unsure_copies": nobody
    may have changed them, an older roadie just did not remember what it wrote.
    State "_written" remembers what roadie wrote (path -> sha256)."""
    written = ctx.state.answers.setdefault("_written", {})
    copies = ctx.extra.setdefault("mine_copies", [])
    unsure = ctx.extra.setdefault("unsure_copies", set())
    for f in files:
        path, new = target(ctx, f, base), f.content.encode()
        if path.is_file():
            old = path.read_bytes()
            if old == new and path.stat().st_mode & 0o777 == f.mode:
                written[f.path] = _sha(new)
                continue
            if f.path in written:
                changed = old != new and _sha(old) != written[f.path]
            else:  # first run with this roadie: only a difference beyond roadie's header counts
                changed = _without_header(old) != _without_header(new)
            if changed:
                copy = _copy_path(path)
                # keeps mode (secrets stay 0600) and times; the copy is briefly created with the
                # umask first, which is fine: the stack dir is 0700 and /etc files are not secret
                shutil.copy2(path, copy)
                st = path.stat()
                if (st.st_uid, st.st_gid) != (os.getuid(), os.getgid()):
                    os.chown(copy, st.st_uid, st.st_gid)  # root only; roadie runs as root
                copies.append((f.path, str(copy)))
                if f.path not in written:
                    unsure.add(str(copy))
        system.write_files([f], base, ctx.paths.root)
        written[f.path] = _sha(new)
